// French B1 practice rooms: 6 modules x 12 rooms x 3 questions.
window.frRooms = window.frRooms || {};
window.frRooms.B1 = [
  // Module 1: Expressing Opinions
  [
    {t:"Opinion starters",s:"Vocabulary",qs:[{q:"What does 'À mon avis' mean?",opts:["On my advice","In my absence","By my account","In my opinion"],a:3,ex:"'Avis' means opinion, so 'à mon avis' introduces your personal point of view."}, {q:"Which phrase means 'I agree'?",opts:["Je suis d'avis","J'ai raison","Je suis d'accord","Je suis sûr"],a:2,ex:"'Être d'accord' is the fixed expression for agreeing; 'j'ai raison' means 'I am right'."}, {q:"What does the verb 'convaincre' mean?",opts:["to complain","to convince","to conclude","to contradict"],a:1,ex:"Convaincre quelqu'un = make someone believe something; compare English 'convince'."}]},
    {t:"Agree, disagree, nuance",s:"Vocabulary",qs:[{q:"What is the opposite of 'Je suis d'accord'?",opts:["Je ne suis pas d'accord","Je suis tout à fait d'accord","Je suis plutôt d'accord","Je suis bien d'accord"],a:0,ex:"Ne ... pas around 'suis' negates the phrase; the other options all express agreement."}, {q:"What does 'd'un côté ... de l'autre' mean?",opts:["from one side to the other","on one side of the road","one after the other, in turn","on the one hand ... on the other"],a:3,ex:"'Côté' means side: the phrase weighs two sides of an argument against each other."}, {q:"Which word belongs to the same family as 'convaincre'?",opts:["convenable","convoquer","convaincant","contenir"],a:2,ex:"Convaincant (convincing) is the present-participle adjective of convaincre."}]},
    {t:"Sounds of opinions",s:"Pronunciation",qs:[{q:"Listen. How is 'mon avis' linked in speech?",opts:["n is silent, then a pause","n links to avis: mo-navis","the s of avis is said","mon rhymes with 'moan'"],a:1,ex:"Liaison: the n of 'mon' is pronounced before a vowel; the final s of 'avis' stays silent.",say:"À mon avis"}, {q:"Listen. The letters 'ain' in 'convaincre' sound like the vowel in:",opts:["vin","laine","banc","bon"],a:0,ex:"'ain' is the nasal vowel [ɛ̃], the same sound as in 'vin' and 'pain'.",say:"convaincre"}, {q:"Listen. Which word of the standard negation has been dropped?",opts:["pas","suis","je","ne"],a:3,ex:"In casual speech 'ne' is often dropped; 'pas' alone carries the negation.",say:"Je suis pas d'accord."}]},
    {t:"Je pense que + indicative",s:"Grammar",qs:[{q:"Je pense qu'il ___ raison.",opts:["ait","avoir","a","ayant"],a:2,ex:"Affirmative 'je pense que' states a belief, so it takes the indicative: il a raison."}, {q:"Je trouve que ce film ___ trop long.",opts:["soit","est","être","étant"],a:1,ex:"'Je trouve que' gives a firm opinion and is followed by a normal indicative verb."}, {q:"Je ne pense pas que ce ___ une bonne idée.",opts:["soit","sois","être","étant"],a:0,ex:"Negative 'je ne pense pas que' expresses doubt and triggers the subjunctive: ce soit."}]},
    {t:"Doubt and the subjunctive",s:"Grammar",qs:[{q:"Which sentence is correct?",opts:["Je ne crois pas qu'il venir.","Je ne crois pas qu'il venant.","Je ne crois pas qu'il viens.","Je ne crois pas qu'il vienne."],a:3,ex:"Negated 'croire que' takes the subjunctive; il vienne is the subjunctive of venir."}, {q:"Je ne suis pas sûr qu'elle ___ venir.",opts:["peux","puisses","puisse","pouvant"],a:2,ex:"'Ne pas être sûr que' expresses doubt, so use the subjunctive, 3rd person: elle puisse."}, {q:"Which sentence contains a mistake?",opts:["Je pense qu'il est malade.","Je pense qu'il soit malade.","Je ne pense pas qu'il soit malade.","Il me semble qu'il est malade."],a:1,ex:"Affirmative 'je pense que' needs the indicative; the subjunctive only follows the negative form."}]},
    {t:"Reading: forum opinions",s:"Reading",qs:[{q:"Julie : « À mon avis, il faut interdire les voitures dans le centre-ville. L'air serait plus propre. » What does Julie want?",opts:["A car ban in the city centre","More parking in the centre","Cheaper public transport","Wider roads in the city"],a:0,ex:"'Interdire les voitures' means to ban cars; she gives cleaner air as her reason."}, {q:"Marc : « Je trouve que le télétravail est pratique car je ne perds pas de temps dans les transports. Pourtant, mes collègues me manquent. » What does Marc miss?",opts:["His commute","His old office","His free time","His colleagues"],a:3,ex:"'Mes collègues me manquent' = I miss my colleagues; manquer à works the other way round."}, {q:"Léa : « D'un côté, les réseaux sociaux nous informent ; de l'autre, ils nous rendent dépendants. » What is Léa's view?",opts:["They are only useful","They are only harmful","They have pros and cons","She has no opinion"],a:2,ex:"'D'un côté ... de l'autre' balances an advantage (informing) against a drawback (dependence)."}]},
    {t:"Listening: opinions",s:"Listening",qs:[{q:"Listen. What does the speaker think of the restaurant?",opts:["It is too noisy","It is too expensive","It is too far away","It is too small"],a:1,ex:"'Trop cher' means too expensive; 'à mon avis' marks it as a personal opinion.",say:"À mon avis, ce restaurant est trop cher."}, {q:"Listen. Does the speaker agree?",opts:["Yes, completely","No, not at all","Only partly","They don't say"],a:0,ex:"'Tout à fait d'accord' means fully in agreement; 'tout à fait' = completely.",say:"Je suis tout à fait d'accord avec toi."}, {q:"Listen. What is the speaker's view about leaving now?",opts:["It's a great idea","It's absolutely necessary","It's already too late","It's not a good idea"],a:3,ex:"'Je ne pense pas que ce soit une bonne idée' = I don't think it's a good idea.",say:"Je ne pense pas que ce soit une bonne idée de partir maintenant."}]},
    {t:"Agreeing and disagreeing",s:"Speaking",qs:[{q:"A friend says: « Ce film était génial ! » You politely disagree. What do you say?",opts:["Moi aussi, je l'ai vraiment adoré.","Tu as tout à fait raison, il est top.","Moi, je ne l'ai pas trouvé terrible.","Je suis bien d'accord avec toi."],a:2,ex:"'Pas terrible' is a soft, common way to say 'not great'; the others all agree."}, {q:"How do you ask someone for their opinion?",opts:["Qu'est-ce que tu en fais ?","Qu'est-ce que tu en penses ?","À quoi tu penses ?","Comment tu vas ?"],a:1,ex:"'Penser de' asks for an opinion; 'en' replaces 'de ça': what do you think of it?"}, {q:"You agree only partly. What do you say?",opts:["Je suis d'accord, mais pas complètement.","Je suis entièrement d'accord avec ça.","Je ne suis pas du tout d'accord.","Je n'ai vraiment aucune opinion."],a:0,ex:"'Mais pas complètement' adds a limit to your agreement, showing a nuanced view."}]},
    {t:"Writing: a forum reply",s:"Writing",qs:[{q:"Choose the correctly written sentence.",opts:["Je suis d'accord à toi.","J'ai d'accord avec toi.","Je suis d'accord de toi.","Je suis d'accord avec toi."],a:3,ex:"The expression is 'être d'accord avec quelqu'un' – with être and the preposition avec."}, {q:"Je préfère le train ___ c'est plus écologique.",opts:["donc","mais","car","pourtant"],a:2,ex:"'Car' introduces a reason, like 'parce que'; donc gives a consequence, mais/pourtant contrast."}, {q:"Which sentence is written correctly?",opts:["Il semble me que tu as raison.","Il me semble que tu as raison.","Me il semble que tu as raison.","Il me semble que tu avoir raison."],a:1,ex:"The object pronoun 'me' goes before the verb, and 'il me semble que' takes the indicative."}]},
    {t:"Debate culture",s:"Culture",qs:[{q:"Lively debate at a French dinner table is usually seen as:",opts:["a normal, enjoyable part of social life","a sign that the meal went badly","something only politicians do","rude and always avoided"],a:0,ex:"In France, discussing and arguing ideas over a meal is a valued social habit."}, {q:"Which way of giving an opinion sounds the most formal?",opts:["Pour moi, ...","Moi, je trouve que...","Franchement, ...","Il me semble que..."],a:3,ex:"'Il me semble que' is cautious and impersonal, so it suits formal speech and writing."}, {q:"A French speaker answers your question with 'Bof...'. What does this show?",opts:["Great excitement","Strong disagreement","Little enthusiasm","Polite thanks"],a:2,ex:"'Bof' is a very common shrug-word meaning 'meh, not really convinced'."}]},
    {t:"Opinions review",s:"Review",qs:[{q:"What does 'Je trouve que...' mean when giving an opinion?",opts:["I found out that...","I think that...","I try that...","I am looking for..."],a:1,ex:"With 'que', trouver means to find in the sense of to judge or think, not to locate."}, {q:"Je ne suis pas sûre que nous ___ raison.",opts:["ayons","ayez","avoir","aient"],a:0,ex:"Doubt with 'pas sûr(e) que' needs the subjunctive; for nous, avoir becomes ayons."}, {q:"Which connector gives a reason?",opts:["pourtant","cependant","sinon","parce que"],a:3,ex:"'Parce que' explains why; pourtant and cependant mark contrast, sinon means otherwise."}]},
    {t:"Opinion challenge",s:"Challenge",qs:[{q:"Which sentence correctly expresses doubt?",opts:["Je doute qu'il a raison.","Je doute qu'il avoir raison.","Je doute qu'il ait raison.","Je doute qu'il ayant raison."],a:2,ex:"'Douter que' always expresses uncertainty, so it takes the subjunctive: qu'il ait."}, {q:"Il m'a ___ de rester encore un peu.",opts:["convaincre","convaincu","convainquant","convaincant"],a:1,ex:"In the passé composé you need the past participle of convaincre: convaincu."}, {q:"Which sentence balances two sides correctly?",opts:["D'un côté c'est pratique, de l'autre c'est cher.","D'un côté c'est pratique, d'autre c'est cher.","D'un côté c'est pratique, à l'autre c'est cher.","Du côté c'est pratique, de l'autre c'est cher."],a:0,ex:"The fixed pair is 'd'un côté ... de l'autre (côté)'; both parts keep the preposition de."}]}
  ],
  // Module 2: Subordinate Clauses
  [
    {t:"Time connectors",s:"Vocabulary",qs:[{q:"What does 'pendant que' mean?",opts:["during the","until","as soon as","while"],a:3,ex:"'Pendant que' + clause links two actions happening at the same time."}, {q:"What does 'dès que' mean?",opts:["even though","so that","as soon as","unless"],a:2,ex:"'Dès que' marks the moment one action immediately follows another."}, {q:"What does 'pourtant' mean?",opts:["therefore","yet / however","because","besides"],a:1,ex:"'Pourtant' introduces a surprising contrast: Il est riche, pourtant il est triste."}]},
    {t:"Conjunctions with que",s:"Vocabulary",qs:[{q:"What does 'bien que' mean?",opts:["although","as well as","because","as long as"],a:0,ex:"'Bien que' concedes a fact that doesn't stop the main action; it takes the subjunctive."}, {q:"What does 'pour que' mean?",opts:["because","even if","as soon as","so that"],a:3,ex:"'Pour que' expresses a purpose for someone else and is followed by the subjunctive."}, {q:"Which conjunction is the opposite of 'avant que'?",opts:["bien que","pour que","après que","alors que"],a:2,ex:"Avant que = before, après que = after; both describe the order of events."}]},
    {t:"Sounds in connectors",s:"Pronunciation",qs:[{q:"Listen. The 'eu' in 'pleuve' sounds like the vowel in:",opts:["nous","neuf","nez","nu"],a:1,ex:"Before a pronounced consonant, 'eu' is the open sound [œ], as in neuf and fleur.",say:"Bien qu'il pleuve"}, {q:"Listen. Is the s in 'lorsque' pronounced?",opts:["Yes, lors-que","No, it is silent","Only before a vowel","Yes, but like a z"],a:0,ex:"The s of lorsque is always heard; the word is said 'lors-que' in two parts.",say:"lorsque"}, {q:"Listen. How does the word 'dont' end?",opts:["with a clear t sound","with n and then t","like English 'don't'","nasal 'on', t silent"],a:3,ex:"'dont' is said [dɔ̃]: a nasal vowel, and the final t is silent.",say:"dont"}]},
    {t:"qui, que, où, dont",s:"Grammar",qs:[{q:"Le livre ___ est sur la table est à moi.",opts:["que","où","qui","dont"],a:2,ex:"'Qui' is the subject of the relative clause: the book (it) is on the table."}, {q:"La ville ___ je suis né est petite.",opts:["que","où","qui","dont"],a:1,ex:"'Où' replaces a place (or time) in the relative clause: I was born there."}, {q:"Le film ___ tu m'as parlé est excellent.",opts:["dont","que","qui","où"],a:0,ex:"'Parler de quelque chose' – dont replaces de + noun: the film you told me about."}]},
    {t:"Subjunctive after conjunctions",s:"Grammar",qs:[{q:"Bien qu'il ___ froid, nous sortons.",opts:["fais","faire","faisons","fasse"],a:3,ex:"'Bien que' always takes the subjunctive; faire becomes il fasse."}, {q:"Je t'explique la règle pour que tu ___.",opts:["comprenne","comprendre","comprennes","comprenant"],a:2,ex:"'Pour que' + subjunctive; for tu the form is comprennes, with -es."}, {q:"Which conjunction is followed by the indicative?",opts:["bien que","parce que","pour que","avant que"],a:1,ex:"'Parce que' gives a real cause, so it takes the indicative; the others need the subjunctive."}]},
    {t:"Reading: linked sentences",s:"Reading",qs:[{q:"Message : « Si tu viens samedi, on ira au marché. Apporte le livre dont je t'ai parlé ! » What happens if the friend comes on Saturday?",opts:["They will go to the market","They will read a book together","They will cook dinner","They will go to a bookshop"],a:0,ex:"'Si tu viens, on ira au marché': si + present leads to a future result."}, {q:"« Je reste chez moi ce soir parce que je suis malade, bien que mes amis organisent une fête. » Why is the writer staying home?",opts:["Because there is no party","Because their friends are away","Because it is raining","Because they are ill"],a:3,ex:"'Parce que je suis malade' gives the reason; 'bien que' only adds what they miss."}, {q:"« Le quartier où j'habite est calme, pourtant il est près du centre. » What is true about the area?",opts:["It is noisy and central","It is quiet and far away","It is quiet but central","It is noisy and far away"],a:2,ex:"'Pourtant' signals that being quiet is surprising for a place near the centre."}]},
    {t:"Listening: when and if",s:"Listening",qs:[{q:"Listen. When will the speaker call?",opts:["Before leaving home","When they reach the station","While on the train","After dinner tonight"],a:1,ex:"'Dès que j'arrive à la gare' = as soon as I arrive at the station.",say:"Dès que j'arrive à la gare, je t'appelle."}, {q:"Listen. What does the speaker lack in order to travel?",opts:["time","money","a passport","a friend"],a:0,ex:"'Si j'avais le temps' (if I had time): si + imparfait with conditional is hypothetical.",say:"Si j'avais le temps, je voyagerais en Italie."}, {q:"Listen. What will the speaker do while the other person cooks?",opts:["Do the shopping","Wash the dishes","Phone a friend","Set the table"],a:3,ex:"'Pendant que tu cuisines, je mets la table' – mettre la table = to set the table.",say:"Pendant que tu cuisines, je mets la table."}]},
    {t:"Speaking: complex answers",s:"Speaking",qs:[{q:"Friend: « Tu viens ce soir ? » You'll come although you're tired. What do you say?",opts:["Oui, parce que je sois fatigué.","Oui, pour que je sois fatigué.","Oui, bien que je sois fatigué.","Oui, dès que je sois fatigué."],a:2,ex:"Only 'bien que' means although, and it correctly takes the subjunctive je sois."}, {q:"A colleague asks when you'll send the report. What do you answer?",opts:["Bien que je le termine, je te l'envoie.","Dès que je le termine, je te l'envoie.","Pour que je le termine, je te l'envoie.","Pendant que je l'envoie, je le termine."],a:1,ex:"'Dès que' = as soon as; the report is sent right after it is finished."}, {q:"« Qu'est-ce que tu ferais si tu gagnais au loto ? » Best answer:",opts:["Je ferais le tour du monde.","Je fais le tour du monde.","J'ai fait le tour du monde.","Je faisais le tour du monde."],a:0,ex:"A hypothetical question in the conditional (ferais) is answered in the conditional."}]},
    {t:"Writing: join the sentences",s:"Writing",qs:[{q:"Join: 'J'ai une amie. Son frère est pilote.'",opts:["J'ai une amie que le frère est pilote.","J'ai une amie qui le frère est pilote.","J'ai une amie où le frère est pilote.","J'ai une amie dont le frère est pilote."],a:3,ex:"'Dont' replaces a possessive link (le frère de l'amie) = whose."}, {q:"Which 'si' sentence is correct?",opts:["Si j'aurais de l'argent, j'achèterais une maison.","Si j'avais de l'argent, j'achète une maison.","Si j'avais de l'argent, j'achèterais une maison.","Si j'ai de l'argent, j'achèterais une maison."],a:2,ex:"Hypothesis: si + imparfait, then conditional; never put the conditional after si."}, {q:"Il est parti ___ je sois arrivé.",opts:["parce que","avant que","pendant que","dès que"],a:1,ex:"Only 'avant que' takes the subjunctive here (je sois arrivé); the others need the indicative."}]},
    {t:"Grammar and usage",s:"Culture",qs:[{q:"Which word for 'when' sounds more formal or written?",opts:["lorsque","quand","dès","puis"],a:0,ex:"'Lorsque' and 'quand' mean the same, but lorsque is preferred in careful writing."}, {q:"The Académie française says 'après que' should be followed by:",opts:["the subjunctive","the infinitive","the conditional","the indicative"],a:3,ex:"After que describes facts that happened, so the norm is indicative, though many use the subjunctive."}, {q:"A famous line from 'La Guerre des boutons' is the child's mistake 'Si j'aurais su, j'aurais pas venu'. What is the correct form?",opts:["Si j'avais su, je ne suis pas venu.","Si je savais, je ne serai pas venu.","Si j'avais su, je ne serais pas venu.","Si j'ai su, je ne serais pas venu."],a:2,ex:"Past hypothesis: si + plus-que-parfait, then conditional past; venir uses être."}]},
    {t:"Clauses review",s:"Review",qs:[{q:"Il est riche, ___ il n'est pas heureux.",opts:["donc","pourtant","car","parce que"],a:1,ex:"The second idea contradicts what we expect from the first, so a contrast word is needed."}, {q:"C'est le restaurant ___ nous avons dîné hier.",opts:["où","que","qui","dont"],a:0,ex:"The restaurant is the place where we ate, so the relative pronoun of place is où."}, {q:"Nous partirons ___ il sera là.",opts:["bien qu'","pour qu'","avant qu'","dès qu'"],a:3,ex:"'Dès que' takes the indicative (here future: il sera); the others would need the subjunctive."}]},
    {t:"Clauses challenge",s:"Challenge",qs:[{q:"J'étudie ___ trouver un bon travail.",opts:["pour que","bien que","pour","afin que"],a:2,ex:"Same subject in both parts (I study, I find), so use pour + infinitive, not pour que."}, {q:"L'homme ___ la voiture est rouge habite ici.",opts:["que","dont","qui","où"],a:1,ex:"The car belongs to the man (la voiture de l'homme), so dont expresses 'whose'."}, {q:"S'il ___ beau demain, nous irons à la plage.",opts:["fait","faisait","fera","ferait"],a:0,ex:"Real condition: si + present, then future; never use future or conditional after si."}]}
  ],
  // Module 3: Work, Media & Reported Speech
  [
    {t:"Applying for a job",s:"Vocabulary",qs:[{q:"What is 'la candidature'?",opts:["the candidate","the interview","the salary","the application"],a:3,ex:"'Poser sa candidature' = to apply; the person applying is le/la candidat(e)."}, {q:"What is 'l'employeur'?",opts:["the employee","the job","the employer","unemployment"],a:2,ex:"-eur is the one who acts: l'employeur employs; the worker is l'employé(e)."}, {q:"What does 'le salaire' mean?",opts:["the sales","the salary","the office","the meeting"],a:1,ex:"'Le salaire' is the pay you receive for your work, usually monthly in France."}]},
    {t:"News and media",s:"Vocabulary",qs:[{q:"What is 'une émission'?",opts:["a TV or radio programme","an email message","an emotional reaction","an art exhibition"],a:0,ex:"'Une émission' is a TV or radio programme; it is a false friend of 'emission'."}, {q:"On French TV, 'le journal de 20 heures' is:",opts:["a newspaper delivery","a work diary","a weather chart","the evening news"],a:3,ex:"'Le journal' means both a newspaper and the TV news; 'les infos' is the casual word."}, {q:"What does 'selon' mean in 'selon le journal'?",opts:["instead of","against","according to","without"],a:2,ex:"'Selon' attributes information to a source: selon les experts = according to experts."}]},
    {t:"Workplace sounds",s:"Pronunciation",qs:[{q:"Listen. The 'u' in 'candidature' is the same sound as in:",opts:["tout","tu","tôt","thé"],a:1,ex:"French 'u' [y] is said with rounded lips and the tongue forward, as in tu.",say:"la candidature"}, {q:"Listen. 'Employeur' ends with the same sound as:",opts:["fleur","four","faire","fort"],a:0,ex:"'-eur' is pronounced [œʁ], rhyming with fleur and peur.",say:"l'employeur"}, {q:"Listen. How many syllables does 'réunion' have?",opts:["2","4","1","3"],a:3,ex:"It is ré-u-nion: 'ni' glides into 'on', so 'nion' is one syllable.",say:"la réunion"}]},
    {t:"Reported speech: tenses",s:"Grammar",qs:[{q:"« Je suis fatigué. » → Il a dit qu'il ___ fatigué.",opts:["est été","soit","était","être"],a:2,ex:"After a past reporting verb, the present shifts to the imparfait: suis → était."}, {q:"« Je viendrai. » → Elle a dit qu'elle ___.",opts:["viendrais","viendrait","vienne","venir"],a:1,ex:"After a past reporting verb, the futur becomes the conditionnel: viendrai → viendrait."}, {q:"« J'aime ce travail. » → Il dit qu'il ___ ce travail.",opts:["aime","aimait","aimerait","aima"],a:0,ex:"When the reporting verb is in the present (il dit), the tense does not change."}]},
    {t:"Passive and reported questions",s:"Grammar",qs:[{q:"Le produit ___ en France.",opts:["a fabriqué","fabrique","est fabriquée","est fabriqué"],a:3,ex:"Passive = être + past participle agreeing with the subject (le produit, masculine)."}, {q:"Choose the passive version of 'Le journaliste écrit l'article.'",opts:["L'article a écrit le journaliste.","L'article est écrite par le journaliste.","L'article est écrit par le journaliste.","L'article écrit par le journaliste."],a:2,ex:"The object becomes the subject, être + participle, and the agent is introduced by par."}, {q:"« Tu travailles où ? » → Il m'a demandé ___ je travaillais.",opts:["que","où","si","ce que"],a:1,ex:"In a reported question the question word stays: où; si is only for yes/no questions."}]},
    {t:"Reading: ads and emails",s:"Reading",qs:[{q:"« Entreprise lyonnaise cherche assistant(e) commercial(e). Deux ans d'expérience exigés. Envoyez votre candidature avant le 15 mars. » What must applicants have?",opts:["Two years' experience","A degree from Lyon","A car","Fluent English"],a:0,ex:"'Deux ans d'expérience exigés' = two years of experience required."}, {q:"« Selon la météo, de fortes pluies sont attendues dans le sud. Par conséquent, plusieurs routes seront fermées. » Why will roads be closed?",opts:["There is a strike","There are roadworks","Snow has fallen","Heavy rain is expected"],a:3,ex:"'Par conséquent' links the closures to the cause: fortes pluies attendues."}, {q:"« Bonjour à tous, la réunion de lundi est reportée à mercredi 10 h. Merci de confirmer votre présence. » What happened to Monday's meeting?",opts:["It was cancelled","It was moved to Monday 10am","It was moved to Wednesday","It was moved online"],a:2,ex:"'Reporter' in the workplace means to postpone: the meeting is now on Wednesday."}]},
    {t:"Listening: news and work",s:"Listening",qs:[{q:"Listen. What did the director say?",opts:["He was already there","He would arrive late","He wouldn't come","He had left early"],a:1,ex:"'Il a dit qu'il arriverait en retard': reported future in the conditional.",say:"Le directeur a dit qu'il arriverait en retard."}, {q:"Listen. According to the news, what will happen?",opts:["Fuel prices will rise","Fuel will get cheaper","Newspapers will cost more","Trains will be free"],a:0,ex:"'Selon le journal' = according to the news; 'augmenter' means to go up.",say:"Selon le journal, le prix de l'essence va encore augmenter."}, {q:"Listen. What is the speaker's situation?",opts:["They got the job","They were rejected","They haven't applied yet","They applied but have no reply"],a:3,ex:"'J'ai envoyé ma candidature' (I applied) 'mais je n'ai pas encore de réponse' (no answer yet).",say:"J'ai envoyé ma candidature, mais je n'ai pas encore de réponse."}]},
    {t:"Speaking at work",s:"Speaking",qs:[{q:"Interviewer: « Pourquoi voulez-vous travailler chez nous ? » Best answer:",opts:["Parce que je travaille chez moi le lundi.","Oui, je voudrais bien, merci.","Parce que vos projets m'intéressent beaucoup.","Je suis arrivé en métro ce matin."],a:2,ex:"The question asks for a reason, so answer with parce que and a motivation."}, {q:"Your colleague said « J'ai faim ». You report it later. What do you say?",opts:["Elle a dit qu'elle a eu faim.","Elle a dit qu'elle avait faim.","Elle a dit qu'elle aurait faim.","Elle a dit qu'elle avoir faim."],a:1,ex:"Reported after a past verb, the present 'j'ai' shifts to the imparfait 'elle avait'."}, {q:"On the phone you want to speak to Mr Martin. What do you say?",opts:["Pourrais-je parler à M. Martin ?","Je peux parler de M. Martin ?","Passe-moi Martin, toi !","Tu es M. Martin, non ?"],a:0,ex:"The conditional 'pourrais-je' is the polite, professional way to ask on the phone."}]},
    {t:"Writing: work messages",s:"Writing",qs:[{q:"How do you open a formal letter to an unknown company?",opts:["Salut à tous,","Coucou,","Cher ami,","Madame, Monsieur,"],a:3,ex:"'Madame, Monsieur,' is the standard neutral greeting when you don't know the reader."}, {q:"Choose the correctly written reported question.",opts:["Elle m'a demandé que j'étais libre.","Elle m'a demandé est-ce que j'étais libre.","Elle m'a demandé si j'étais libre.","Elle m'a demandé si étais-je libre."],a:2,ex:"A reported yes/no question uses si + normal word order, with no est-ce que or inversion."}, {q:"Il y a une grève des trains ; ___, je travaille de chez moi.",opts:["pourtant","par conséquent","bien que","parce que"],a:1,ex:"The strike causes working from home, so a connector of consequence is needed."}]},
    {t:"The French workplace",s:"Culture",qs:[{q:"In France, 'les 35 heures' refers to:",opts:["the legal working week","the length of a TV series","the time to get a visa","the hours shops open"],a:0,ex:"Since 2000, the legal full-time working week in France is 35 hours."}, {q:"RFI's 'Journal en français facile' is:",opts:["a printed business newspaper","a TV cooking show","a job-search website","a daily radio news in simple French"],a:3,ex:"Radio France Internationale broadcasts this news bulletin in slower, simpler French for learners."}, {q:"Where would you write 'Je vous prie d'agréer, Madame, Monsieur, mes salutations distinguées'?",opts:["At the start of a text message","As a toast at dinner","At the end of a formal letter","When greeting a colleague"],a:2,ex:"This is the traditional closing formula of a formal French letter or cover letter."}]},
    {t:"Work and media review",s:"Review",qs:[{q:"Which word is NOT about getting a job?",opts:["le salaire","l'émission","l'employeur","la candidature"],a:1,ex:"'L'émission' is a TV or radio programme; the others belong to work and applications."}, {q:"« Nous partons demain. » → Ils ont dit qu'ils ___ le lendemain.",opts:["partaient","partir","partons","partant"],a:0,ex:"Reported present shifts to the imparfait, and 'demain' becomes 'le lendemain'."}, {q:"Je suis malade, ___ je reste à la maison.",opts:["car","bien que","pourtant","donc"],a:3,ex:"'Donc' introduces a consequence: being ill leads to staying at home."}]},
    {t:"Media challenge",s:"Challenge",qs:[{q:"« Je vais démissionner. » → Il a dit qu'il ___ démissionner.",opts:["allant","aller","allait","allions"],a:2,ex:"Futur proche reported in the past: aller shifts to the imparfait, il allait + infinitive."}, {q:"Les lettres ___ hier par la secrétaire.",opts:["ont envoyé","ont été envoyées","sont envoyé","ont été envoyés"],a:1,ex:"Passive in the passé composé is avoir été + participle, agreeing with les lettres (f. pl.)."}, {q:"« Avez-vous de l'expérience ? » → Elle lui a demandé ___ de l'expérience.",opts:["s'il avait","si il avait","qu'il avait","s'il avoir"],a:0,ex:"A yes/no question is reported with si, which elides before il (s'il), plus imparfait."}]}
  ],
  // Module 4: Advice, Plans & Problem Solving
  [
    {t:"Giving advice",s:"Vocabulary",qs:[{q:"What does 'Tu devrais...' mean?",opts:["You must have...","You owe...","You will...","You should..."],a:3,ex:"'Devrais' is the conditional of devoir, which softens an order into advice."}, {q:"What does 'À ta place, je...' mean?",opts:["In your house, I...","At your seat, I...","If I were you, I...","Instead of you, I..."],a:2,ex:"'À ta place' = in your place; it is followed by the conditional to give advice."}, {q:"What is 'la solution'?",opts:["the problem","the solution","the question","the suggestion"],a:1,ex:"'La solution' answers 'le problème'; trouver une solution = to find a solution."}]},
    {t:"Plans and suggestions",s:"Vocabulary",qs:[{q:"What does 'J'ai l'intention de...' mean?",opts:["I intend to...","I'm paying attention to...","I'm interested in...","I'm tired of..."],a:0,ex:"'Avoir l'intention de' + infinitive states a plan you have decided on."}, {q:"What does 'projeter de' mean?",opts:["to throw","to protect","to promise to","to plan to"],a:3,ex:"'Projeter de faire quelque chose' = to plan to do it, from the noun le projet."}, {q:"What does 'Et si on...?' mean?",opts:["And if not...?","What about him...?","What if we...?","And so we..."],a:2,ex:"'Et si on' + imparfait is a friendly suggestion: Et si on sortait ? = Shall we go out?"}]},
    {t:"Future and conditional sounds",s:"Pronunciation",qs:[{q:"Listen. In everyday speech, 'je partirai' (future) and 'je partirais' (conditional) usually sound:",opts:["completely different","the same or almost the same","different in stress","different in length"],a:1,ex:"Many speakers pronounce -rai and -rais alike, so context and spelling tell them apart.",say:"je partirai, je partirais"}, {q:"Listen. The ending '-ais' in 'devrais' sounds like the vowel in:",opts:["mère","chat","lit","mur"],a:0,ex:"The ending -ais is pronounced as an e sound like è; the s is silent.",say:"Tu devrais"}, {q:"Listen. In 'intention', the t of '-tion' is pronounced like:",opts:["t","ch","nothing","s"],a:3,ex:"In the ending -tion, the t is pronounced [s]: in-ten-sion.",say:"J'ai l'intention de partir."}]},
    {t:"Conditional for advice",s:"Grammar",qs:[{q:"Tu ___ voir un médecin.",opts:["devrait","devrai","devrais","devoir"],a:2,ex:"Advice to 'tu' uses the conditional devrais; devrait is for il/elle, devrai is future."}, {q:"À ta place, je ___ le train.",opts:["prendrai","prendrais","prendrait","prendre"],a:1,ex:"'À ta place' sets up an imagined situation, so use the conditional, je form: prendrais."}, {q:"Vous ___ demander de l'aide à votre collègue.",opts:["pourriez","pourrais","pouvoir","pourrions"],a:0,ex:"For vous the conditional of pouvoir is pourriez; it makes a polite suggestion."}]},
    {t:"Talking about the future",s:"Grammar",qs:[{q:"L'année prochaine, je ___ à Vienne.",opts:["va déménager","vais déménagé","allons déménager","vais déménager"],a:3,ex:"Futur proche = aller (je vais) + infinitive; the infinitive ends in -er, not -é."}, {q:"Demain, nous ___ tôt.",opts:["partirez","partiront","partirons","partirai"],a:2,ex:"Futur simple: infinitive + ending; for nous the ending is -ons: partirons."}, {q:"Quand j'___ 30 ans, j'aurai une maison.",opts:["aurais","aurai","avais","ai"],a:1,ex:"After quand referring to the future, French uses the futur, unlike English 'when I am'."}]},
    {t:"Reading: problems and plans",s:"Reading",qs:[{q:"« Mon voisin fait du bruit tous les soirs. Que dois-je faire ? » Réponse : « À votre place, j'irais lui parler calmement. » What is the advice?",opts:["Talk calmly to the neighbour","Call the police","Move to another flat","Make noise too"],a:0,ex:"'J'irais lui parler calmement' = I would go and talk to him calmly."}, {q:"« Cet été, j'ai l'intention de faire un stage à Montréal. Ensuite, je reprendrai mes études. » What will the writer do after the internship?",opts:["Stay in Montréal","Look for a job","Travel around Canada","Go back to studying"],a:3,ex:"'Reprendre ses études' means to resume one's studies; 'ensuite' = afterwards."}, {q:"« J'ai perdu mon passeport ! » — « Tu devrais d'abord aller au commissariat, puis contacter ton ambassade. » What should be done first?",opts:["Contact the embassy","Buy a new ticket","Go to the police station","Search the hotel"],a:2,ex:"'D'abord' (first) the commissariat, 'puis' (then) the embassy."}]},
    {t:"Listening: suggestions",s:"Listening",qs:[{q:"Listen. What is the speaker suggesting?",opts:["Staying at home tonight","Going to the cinema tonight","Seeing a film tomorrow","Watching TV together"],a:1,ex:"'Et si on allait au cinéma ce soir ?' – et si on + imparfait makes a suggestion.",say:"Et si on allait au cinéma ce soir ?"}, {q:"Listen. What would the speaker do in your place?",opts:["Look for another flat","Paint the flat","Talk to the landlord","Buy a flat"],a:0,ex:"'Je chercherais un autre appartement' = I would look for another flat.",say:"À ta place, je chercherais un autre appartement."}, {q:"Listen. When will the speaker go on holiday?",opts:["Before their exams","During their exams","Next summer, exams or not","After finishing their exams"],a:3,ex:"'Dès que j'aurai fini mes examens' = as soon as I have finished my exams.",say:"Je partirai en vacances dès que j'aurai fini mes examens."}]},
    {t:"Speaking: helping out",s:"Speaking",qs:[{q:"A friend says: « Je suis toujours fatigué. » What advice do you give?",opts:["Tu as dû te coucher plus tôt.","Tu te couchais plus tôt hier.","Tu devrais te coucher plus tôt.","Tu devras te coucher hier."],a:2,ex:"Advice uses the conditional devrais + infinitive, about the future, not the past."}, {q:"You suggest a coffee break to colleagues. Which is correct?",opts:["Et si on prendrait une pause ?","Et si on prenait une pause ?","Et si on prendre une pause ?","Et si on pris une pause ?"],a:1,ex:"'Et si on' is followed by the imparfait (prenait), never the conditional."}, {q:"Colleague: « L'imprimante ne marche plus. » What do you offer?",opts:["Je vais appeler le technicien.","Je vais acheter du pain.","Tu devrais dormir plus.","Je suis d'accord avec toi."],a:0,ex:"The colleague states a problem; a useful reply proposes a concrete solution."}]},
    {t:"Writing: plans",s:"Writing",qs:[{q:"Which sentence about future plans is correct?",opts:["J'ai l'intention à changer de travail.","J'ai intention de changer de travail.","Je suis l'intention de changer de travail.","J'ai l'intention de changer de travail."],a:3,ex:"The fixed phrase is avoir l'intention de + infinitive, with the article l'."}, {q:"L'année prochaine, je ___ à Paris. (être)",opts:["sera","été","serai","seras"],a:2,ex:"The futur simple of être is irregular: je serai, tu seras, il sera."}, {q:"Which sentence has the correct word order?",opts:["Tu ne devrais travailler pas autant.","Tu ne devrais pas travailler autant.","Tu devrais pas ne travailler autant.","Ne tu devrais pas travailler autant."],a:1,ex:"Ne ... pas surrounds the conjugated verb (devrais); the infinitive comes after."}]},
    {t:"Help and services",s:"Culture",qs:[{q:"In France, which emergency number reaches the police?",opts:["17","15","18","911"],a:0,ex:"In France, 17 is the police, 15 the medical SAMU and 18 the fire brigade; 112 works EU-wide."}, {q:"In France, 'la Sécu' is:",opts:["a private security company","a national bank card","a state holiday voucher","the national health insurance"],a:3,ex:"'La Sécu' is short for la Sécurité sociale, which reimburses medical costs."}, {q:"Which piece of advice sounds the most polite to a colleague?",opts:["Faites ça tout de suite.","Vous devez essayer...","Vous pourriez essayer...","Il faut essayer..."],a:2,ex:"The conditional 'pourriez' softens the advice; devez and il faut sound like orders."}]},
    {t:"Advice and plans review",s:"Review",qs:[{q:"Which expression means 'to plan to'?",opts:["rêver de","projeter de","refuser de","oublier de"],a:1,ex:"'Projeter de' + infinitive = to plan to; rêver = dream, refuser = refuse, oublier = forget."}, {q:"Si j'étais toi, je ___.",opts:["me reposerais","me reposerai","me repose","me reposais"],a:0,ex:"'Si j'étais toi' (imparfait) is followed by the conditional in the main clause."}, {q:"Cet été, nous ___ en Espagne. (aller)",opts:["allerons","iront","irez","irons"],a:3,ex:"Aller has the irregular future stem ir-: nous irons."}]},
    {t:"Advice challenge",s:"Challenge",qs:[{q:"Quand tu ___ à Paris la semaine prochaine, tu m'appelleras.",opts:["serais","étais","seras","sois"],a:2,ex:"Quand + future time takes the futur simple in French: quand tu seras."}, {q:"Il ___ mieux partir maintenant, à cause des embouteillages.",opts:["voudrait","vaudrait","vaudrais","vouloir"],a:1,ex:"'Il vaut mieux' (valoir) = it's better; the conditional vaudrait softens the advice."}, {q:"À ta place, je ne ___ pas.",opts:["m'inquiéterais","m'inquiéterai","m'inquiétais","inquiéterais"],a:0,ex:"Advice after 'à ta place' needs the conditional, and s'inquiéter keeps its pronoun me."}]}
  ],
  // Module 5: Essays, Interviews & Review
  [
    {t:"Essay connectors",s:"Vocabulary",qs:[{q:"What does 'Tout d'abord' mean?",opts:["Above all things","After all","Straight away","Firstly"],a:3,ex:"'Tout d'abord' opens the first argument of an essay or speech."}, {q:"What does 'De plus' mean?",opts:["No longer","At most","Moreover","Once more"],a:2,ex:"'De plus' adds a further argument in the same direction."}, {q:"What does 'En somme' mean?",opts:["In summer","In short","In total silence","In some cases"],a:1,ex:"'En somme' introduces a summary, like 'en conclusion' or 'bref'."}]},
    {t:"Interview words",s:"Vocabulary",qs:[{q:"What is 'le point faible' in a job interview?",opts:["the weakness","the low point","the full stop","the tired moment"],a:0,ex:"Le point fort = strength, le point faible = weakness; both are classic interview topics."}, {q:"What does 'postuler à un poste' mean?",opts:["to post a letter","to quit a job","to promote someone","to apply for a job"],a:3,ex:"'Postuler à' + job = to apply; la candidature is the application itself."}, {q:"What does 'avoir de l'expérience en gestion' mean?",opts:["to try management","to experiment with management","to have experience in management","to have studied management"],a:2,ex:"'Avoir de l'expérience en' + field states practical work experience in that area."}]},
    {t:"Essay and interview sounds",s:"Pronunciation",qs:[{q:"Listen. Is the final t of 'part' pronounced?",opts:["Yes, always","No, it is silent","Only in 'd'autre part'","Only before 'de'"],a:1,ex:"The final t of part is silent; d'une part, d'autre part both end in an r sound.",say:"d'une part, d'autre part"}, {q:"Listen. In 'développement', the ending '-ment' sounds like:",opts:["a nasal 'an'","English 'meant'","the word 'mais'","the word 'mine'"],a:0,ex:"-ment is pronounced with the nasal vowel [ɑ̃] and a silent t.",say:"le développement"}, {q:"Listen. How is 'Qu'est-ce qui' pronounced?",opts:["kwest-se-kwi","ke-es-ki","kest-kwi","kes-ki"],a:3,ex:"'Qu'est-ce qui' is said in two quick syllables, 'kes-ki'; qu sounds like k.",say:"Qu'est-ce qui vous motive ?"}]},
    {t:"Linking arguments",s:"Grammar",qs:[{q:"D'une part, c'est cher ; ___, c'est très utile.",opts:["de l'autre part","d'une autre","d'autre part","par autre part"],a:2,ex:"The fixed pair is 'd'une part ... d'autre part' (on the one hand ... on the other)."}, {q:"Which connector adds another argument in the same direction?",opts:["Pourtant","De plus","En revanche","Cependant"],a:1,ex:"'De plus' adds; pourtant, en revanche and cependant introduce a contrast."}, {q:"Which connector introduces an opposing argument?",opts:["En revanche","De plus","En outre","Ensuite"],a:0,ex:"'En revanche' (on the other hand) contrasts; en outre and de plus add, ensuite orders."}]},
    {t:"Interview grammar",s:"Grammar",qs:[{q:"J'ai trois ans d'expérience ___ marketing.",opts:["au","du","par","en"],a:3,ex:"'Expérience en' + field without article: expérience en marketing, en vente."}, {q:"Je postule ___ poste de comptable.",opts:["du","le","au","en"],a:2,ex:"'Postuler à' + le poste contracts to au poste."}, {q:"Choose the correct interview question.",opts:["Qu'est-ce que vous motive ?","Qu'est-ce qui vous motive ?","Qui est-ce que vous motive ?","Qu'est-ce qui vous motivez ?"],a:1,ex:"'Qu'est-ce qui' asks about a thing as subject; the verb agrees with it: motive."}]},
    {t:"Reading: essays and interviews",s:"Reading",qs:[{q:"« Le télétravail permet de gagner du temps. En revanche, il peut isoler les salariés. En conclusion, une formule mixte semble idéale. » What does the author conclude?",opts:["A mix of home and office work is best","Working from home is always better","Office work is always better","Employees prefer to be alone"],a:0,ex:"'Une formule mixte' means a combination, balancing the advantage and drawback."}, {q:"« Quel est votre point faible ? » — « Je suis parfois trop perfectionniste, mais j'apprends à déléguer. » How does the candidate present the weakness?",opts:["As a reason to refuse the job","As a strength of the team","As a problem with their boss","As something they are improving"],a:3,ex:"'J'apprends à déléguer' (I'm learning to delegate) shows they are working on it."}, {q:"« Nous recherchons un(e) réceptionniste bilingue. Pour postuler, envoyez CV et lettre de motivation. » What must you send?",opts:["A photo and a diploma","A CV and references","A CV and a cover letter","A letter and a passport"],a:2,ex:"'La lettre de motivation' is the cover letter that goes with the CV."}]},
    {t:"Listening: an interview",s:"Listening",qs:[{q:"Listen. What does the candidate do first?",opts:["Asks about the salary first","Thanks them for the invitation","Describes their main weakness","Asks for a glass of water"],a:1,ex:"'Je voudrais vous remercier de m'avoir invité' = I would like to thank you for inviting me.",say:"Tout d'abord, je voudrais vous remercier de m'avoir invité."}, {q:"Listen. What strength does the speaker mention?",opts:["Adapting easily","Speaking languages","Working fast","Being punctual"],a:0,ex:"'Je m'adapte facilement' = I adapt easily; 'mon point fort' = my strength.",say:"Mon point fort, c'est que je m'adapte facilement."}, {q:"Listen. What is the speaker's conclusion?",opts:["The drawbacks outweigh the advantages","Both sides are exactly equal","No conclusion is possible","The advantages outweigh the drawbacks"],a:3,ex:"'L'emporter sur' means to win over: the advantages prevail over the drawbacks.",say:"Pour conclure, je dirais que les avantages l'emportent sur les inconvénients."}]},
    {t:"Speaking: job interview",s:"Speaking",qs:[{q:"Interviewer: « Parlez-moi de vous. » Best start:",opts:["Je vous parle de vous, alors ?","Non merci, ça va très bien.","J'ai 28 ans et je travaille dans la vente.","J'ai pris le bus pour venir ici."],a:2,ex:"'Parlez-moi de vous' invites a short professional presentation: age, field, experience."}, {q:"Interviewer: « Qu'est-ce qui vous motive ? » Best answer:",opts:["Oui, je suis très motivé, merci.","Les nouveaux défis et le travail d'équipe.","Je pars en vacances en juillet.","C'est mon frère qui m'a amené."],a:1,ex:"The question asks 'what' motivates you, so answer with things, not just yes."}, {q:"The interview is over. What do you say?",opts:["Merci beaucoup pour cet entretien.","Salut, à plus tard alors !","Bon, ben, j'y vais, hein.","Ciao, bonne soirée les gars !"],a:0,ex:"In an interview you stay formal to the end; 'un entretien' is the interview."}]},
    {t:"Writing: essays and letters",s:"Writing",qs:[{q:"What is the standard order of a French essay?",opts:["développement, introduction, conclusion","conclusion, développement, introduction","introduction, conclusion, développement","introduction, développement, conclusion"],a:3,ex:"A French essay presents the topic, develops arguments, then concludes."}, {q:"Which essay sentence is written correctly?",opts:["Pour conclusion, le télétravail a des avantages.","Par conclure, le télétravail a des avantages.","Pour conclure, le télétravail a des avantages.","À conclusion, le télétravail a des avantages."],a:2,ex:"Use pour + infinitive (pour conclure) or en + noun (en conclusion)."}, {q:"Je vous adresse ma candidature ___ le poste de vendeur.",opts:["à","pour","de","en"],a:1,ex:"In a cover letter, 'ma candidature pour le poste de...' introduces the job you want."}]},
    {t:"Essays and jobs in France",s:"Culture",qs:[{q:"In French applications, 'la lettre de motivation' is:",opts:["a cover letter explaining why you apply","a medical certificate for the employer","a reference letter from a teacher","a list of your hobbies and interests"],a:0,ex:"French employers usually expect a lettre de motivation along with the CV."}, {q:"The classic French essay plan 'plan dialectique' is:",opts:["début, milieu, fin","pour, pour, pour","question, réponse, question","thèse, antithèse, synthèse"],a:3,ex:"The dialectical plan sets out a view, the opposing view, then a balanced synthesis."}, {q:"In a French job interview you normally address the interviewer with:",opts:["tu","on","vous","toi"],a:2,ex:"'Vous' is the polite form expected in professional settings unless invited to use tu."}]},
    {t:"Essays and interviews review",s:"Review",qs:[{q:"Which phrase introduces a conclusion?",opts:["De plus","En conclusion","Tout d'abord","D'une part"],a:1,ex:"'En conclusion' closes an essay; the others open or add arguments."}, {q:"Je ne pense pas que ce poste ___ pour moi.",opts:["soit","sois","être","soient"],a:0,ex:"Negative opinion verbs trigger the subjunctive; ce poste needs the 3rd person singular soit."}, {q:"Le candidat ___ j'ai parlé est très compétent.",opts:["que","qui","où","dont"],a:3,ex:"'Parler de quelqu'un' – dont replaces de + person: the candidate I spoke about."}]},
    {t:"Interview challenge",s:"Challenge",qs:[{q:"Bien que ce poste ___ intéressant, le salaire est trop bas.",opts:["sois","être","soit","étant"],a:2,ex:"'Bien que' requires the subjunctive; for ce poste the form is soit."}, {q:"If I were you, I would apply for this job.",opts:["À ta place, je postulerai à ce poste.","À ta place, je postulerais à ce poste.","À ta place, je postulais à ce poste.","À ta place, j'ai postulé à ce poste."],a:1,ex:"'Would' in advice is the conditional: postulerais, ending in -ais."}, {q:"Which sentence is the best formal ending for an essay?",opts:["En définitive, le débat reste ouvert.","Bref, voilà, c'est tout, quoi.","Alors bon, j'en sais rien, moi.","Et puis voilà, c'est fini, hein."],a:0,ex:"'En définitive' is formal; the others use spoken fillers like voilà, quoi, hein."}]}
  ],
  // Module 6: Pronouns y, en & Describing People
  [
    {t:"Appearance words",s:"Vocabulary",qs:[{q:"What does 'mince' mean?",opts:["short","tall","strong","slim"],a:3,ex:"'Mince' means slim or thin; its opposite in describing people is 'gros' or 'rond'."}, {q:"What does 'costaud' mean?",opts:["tired / weary","bald / hairless","stocky / sturdy","cheerful / happy"],a:2,ex:"'Costaud' describes a strong, solidly built person."}, {q:"What does 'avoir les cheveux courts' mean?",opts:["to have curly hair","to have short hair","to have long hair","to have dark hair"],a:1,ex:"French describes hair with avoir + les cheveux + adjective; court = short."}]},
    {t:"Personality words",s:"Vocabulary",qs:[{q:"What does 'drôle' mean?",opts:["funny","sad","shy","rude"],a:0,ex:"'Drôle' means funny or amusing; un film drôle, une personne drôle."}, {q:"What does 'têtu(e)' mean?",opts:["clever","lazy","kind","stubborn"],a:3,ex:"'Têtu' (from tête, head) describes someone who won't change their mind."}, {q:"What does 'Il a l'air fatigué' mean?",opts:["He has tired air","He breathes tiredly","He looks tired","He seems happy"],a:2,ex:"'Avoir l'air' + adjective = to look or seem; it describes an impression."}]},
    {t:"Pronoun and portrait sounds",s:"Pronunciation",qs:[{q:"Listen. How many syllables does 'J'y vais' have?",opts:["3","2","1","4"],a:1,ex:"J'y is one syllable [ʒi] because je elides before y: j'y-vais.",say:"J'y vais."}, {q:"Listen. The 'ê' in 'têtu' sounds like the vowel in:",opts:["mère","mur","mou","mot"],a:0,ex:"The circumflex ê is pronounced as an open e, like è in mère.",say:"têtu"}, {q:"Listen. Which liaisons do you hear?",opts:["no liaison at all","only ont-t-deux","only deux-z-enfants","ils-z-en and en-n-ont"],a:3,ex:"Liaison is required after ils and after en before a vowel: [il.zɑ̃.nɔ̃].",say:"Ils en ont deux."}]},
    {t:"y and en",s:"Grammar",qs:[{q:"Tu vas à Lyon ? — Oui, j'___ vais.",opts:["en","le","y","lui"],a:2,ex:"'Y' replaces à + place: aller à Lyon → y aller."}, {q:"Tu as des frères ? — Oui, j'___ ai deux.",opts:["y","en","les","leur"],a:1,ex:"'En' replaces de + noun (des frères) and is used with a number: j'en ai deux."}, {q:"Je pense à mon examen. → J'___ pense.",opts:["y","en","le","lui"],a:0,ex:"'Penser à' + thing is replaced by y; for a person you would say je pense à lui."}]},
    {t:"dont and adjective agreement",s:"Grammar",qs:[{q:"Voici le collègue ___ le bureau est à côté du mien.",opts:["que","qui","où","dont"],a:3,ex:"The office belongs to the colleague (le bureau du collègue), so dont = whose."}, {q:"Choose the correct phrase.",opts:["une robe jolie noire","une noire robe jolie","une jolie robe noire","une jolie noire robe"],a:2,ex:"Short common adjectives like joli go before the noun; colours go after."}, {q:"Ils ont les yeux ___.",opts:["bleu","bleus","bleues","bleue"],a:1,ex:"Les yeux is masculine plural, so the adjective takes -s: bleus."}]},
    {t:"Reading: portraits",s:"Reading",qs:[{q:"« Mon grand-père est grand et mince. Il a les cheveux blancs. Il a l'air sévère, mais en fait il est très drôle. » What is true?",opts:["He looks strict but is funny","He is short and stocky","He is strict and serious","He has dark hair"],a:0,ex:"'Il a l'air sévère' = he looks strict; 'en fait' (actually) introduces the truth: funny."}, {q:"« Tu as acheté des pommes ? — Oui, j'en ai pris un kilo. » What does 'en' refer to?",opts:["the shop","the money","the kilo price","the apples"],a:3,ex:"'En' replaces des pommes, the noun introduced by de, with the quantity un kilo."}, {q:"« Je suis allé au Canada avec ma sœur, dont le mari est québécois. » Who is from Quebec?",opts:["The sister","The writer","The sister's husband","The writer's husband"],a:2,ex:"'Dont le mari' = whose husband; dont refers back to ma sœur."}]},
    {t:"Listening: describing people",s:"Listening",qs:[{q:"Listen. How is the brother described?",opts:["Slim with long hair","Stocky with short hair","Tall with curly hair","Stocky with long hair"],a:1,ex:"'Costaud' = stocky, 'les cheveux courts' = short hair.",say:"Mon frère est costaud et il a les cheveux courts."}, {q:"Listen. How many children does the speaker have?",opts:["three","two","none","one"],a:0,ex:"'J'en ai trois': en replaces des enfants and keeps the number trois.",say:"Des enfants ? Oui, j'en ai trois."}, {q:"Listen. What does the speaker say about her?",opts:["She is always tired","She was tired yesterday","She doesn't look tired","She looks tired today"],a:3,ex:"'Elle a l'air fatiguée' = she looks tired; aujourd'hui = today.",say:"Elle a l'air fatiguée aujourd'hui."}]},
    {t:"Speaking: y, en and people",s:"Speaking",qs:[{q:"« Tu vas souvent au cinéma ? » Best answer:",opts:["Oui, j'en vais chaque semaine.","Oui, je le vais chaque semaine.","Oui, j'y vais chaque semaine.","Oui, je vais y chaque semaine."],a:2,ex:"'Au cinéma' is à + place, replaced by y, which goes before the conjugated verb."}, {q:"« Tu veux du café ? » Best answer:",opts:["Oui, j'y veux bien.","Oui, j'en veux bien.","Oui, je en veux bien.","Oui, je veux en bien."],a:1,ex:"'Du café' (de + noun) becomes en; je elides to j' before en."}, {q:"« Comment est ton ami ? » Best answer:",opts:["Il est drôle mais un peu têtu.","Il est à Paris depuis lundi.","Il a vingt euros sur lui.","Il va bien, merci beaucoup."],a:0,ex:"'Comment est...?' asks for a description; 'comment va...?' would ask about health."}]},
    {t:"Writing: portraits",s:"Writing",qs:[{q:"Where does y go? Choose the correct sentence.",opts:["Je ne suis y jamais allé.","Je n'ai y jamais allé.","J'y ne suis jamais allé.","Je n'y suis jamais allé."],a:3,ex:"Y goes right before the auxiliary, inside ne ... jamais; aller takes être."}, {q:"C'est un ___ homme. (old)",opts:["vieux","vieille","vieil","vieilles"],a:2,ex:"Before a masculine noun starting with a vowel or mute h, vieux becomes vieil."}, {q:"Which sentence has correct adjective agreement?",opts:["Elle a les cheveux longues et les yeux verts.","Elle a les cheveux longs et les yeux verts.","Elle a les cheveux longs et les yeux vertes.","Elle a les cheveux long et les yeux vert."],a:1,ex:"Adjectives agree with cheveux and yeux (masc. pl.), not with the person: longs, verts."}]},
    {t:"Idioms about people",s:"Culture",qs:[{q:"What does 'avoir un caractère de cochon' mean?",opts:["to have a bad temper","to eat a lot","to be very messy","to be very brave"],a:0,ex:"This informal idiom describes someone grumpy and difficult to get along with."}, {q:"Complete the common simile: têtu comme ___",opts:["un chat","un poisson","une pomme","une mule"],a:3,ex:"French compares a stubborn person to a mule (or a donkey, un âne)."}, {q:"When a French person says 'Bon, j'y vais !' while standing up, they mean:",opts:["I'm going to buy it.","I'll think about it.","Right, I'm off.","I have some."],a:2,ex:"In everyday speech, 'j'y vais' often just means 'I'm leaving now'."}]},
    {t:"Pronouns and people review",s:"Review",qs:[{q:"In 'J'en ai acheté trois', what does 'en' replace?",opts:["à + a place (there)","de + noun (some of them)","the subject of the verb","a person after à (him)"],a:1,ex:"'En' replaces a noun introduced by de or a quantity: trois de ces choses."}, {q:"La maison ___ j'ai grandi est à la campagne.",opts:["où","que","dont","qui"],a:0,ex:"'Où' refers to the place where something happened: I grew up there."}, {q:"C'est un ___ appartement. (beautiful)",opts:["beau","belle","beaux","bel"],a:3,ex:"Before a masculine noun starting with a vowel, beau becomes bel."}]},
    {t:"Pronoun challenge",s:"Challenge",qs:[{q:"Tu as parlé de ce problème au directeur ? — Oui, je lui ___ ai parlé.",opts:["y","le","en","la"],a:2,ex:"'Parler de quelque chose' – en replaces de ce problème; lui comes before en."}, {q:"Vous avez réfléchi à ma proposition ? — Oui, nous ___ avons réfléchi.",opts:["en","y","lui","la"],a:1,ex:"'Réfléchir à' + thing is replaced by y, placed before the auxiliary."}, {q:"C'est un projet ___ je suis très fier.",opts:["dont","que","qui","où"],a:0,ex:"'Être fier de' takes de, so the relative pronoun is dont."}]}
  ]
];
